#include "robot_name.h"

#include <cassert>
#include <cctype>
#include <cstdio>
#include <string>
#include <unordered_set>

using namespace std;

static bool validate_name(const string& name)
{
    if (name.length() != 5)
        return false;
    return isupper(name[0]) && isupper(name[1]) && isdigit(name[2])
        && isdigit(name[3]) && isdigit(name[4]);
}

int main()
{
    // has_a_name
    {
        const robot_name::robot robot;
        assert(validate_name(robot.name()));
    }

    // name_is_the_same_each_time
    {
        const robot_name::robot robot;
        assert(robot.name() == robot.name());
    }

    // different_robots_have_different_names
    {
        const robot_name::robot robot_one;
        const robot_name::robot robot_two;
        assert(robot_one.name() != robot_two.name());
    }

    // is_able_to_reset_name
    {
        robot_name::robot robot;
        const auto original_name = robot.name();
        robot.reset();
        assert(original_name != robot.name());
    }

    // exhausting_digits_yields_different_names
    {
        robot_name::robot robot;
        unordered_set<string> names;
        names.insert(robot.name());
        for (int i = 0; i < 1000; ++i) {
            robot.reset();
            assert(names.count(robot.name()) == 0);
            assert(validate_name(robot.name()));
            names.insert(robot.name());
        }
    }

    printf("All 5 test cases passed.\n");
    return 0;
}

